CREATE COLUMN TABLE "TEST_AP"."SPP2" ("ItemCode" NVARCHAR(50) NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "SPP1LNum" SMALLINT CS_INT NOT NULL , "SPP2LNum" SMALLINT CS_INT NOT NULL , "Amount" DECIMAL(21,6) CS_FIXED, "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "Discount" DECIMAL(21,6) CS_FIXED, "UomEntry" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("CardCode", "ItemCode", "SPP1LNum", "SPP2LNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "SPP2_CARD" ON "TEST_AP"."SPP2" ( "CardCode" ASC );
CREATE INDEX "SPP2_ITEM" ON "TEST_AP"."SPP2" ( "ItemCode" ASC );
CREATE INDEX "SPP2_CURRENCY" ON "TEST_AP"."SPP2" ( "Currency" ASC )